contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, address distributor, address token, uint256 stakeAmount, uint256 rewardAmount) public {
        require(staker != address(0));
        require(distributor != address(0));
        require(token != address(0));
        require(stakeAmount > 0);
        require(rewardAmount > 0);

        c.setRewardDistributor(distributor);
        c.addReward(token);

        uint256 stakeBefore = c.balanceOf(staker);
        uint256 supplyBefore = c.totalSupply();
        uint256 rptBefore = c.rewardPerToken(token);
        uint256 paidBefore = c.userRewardPerTokenPaid(staker, token);
        uint256 claimableBefore = c.claimableRewards(staker, token);

        uint256 earnedBefore = c.earned(staker, token);

        uint256 expectedBefore = (stakeBefore * (rptBefore - paidBefore)) / 1e18 + claimableBefore;
        assert(earnedBefore == expectedBefore);

        uint256 earnedAfter = c.earned(staker, token);
        assert(earnedAfter == earnedBefore);

        uint256 rptAfter = c.rewardPerToken(token);
        uint256 paidAfter = c.userRewardPerTokenPaid(staker, token);
        uint256 claimableAfter = c.claimableRewards(staker, token);
        uint256 balanceAfter = c.balanceOf(staker);

        uint256 expectedAfter = (balanceAfter * (rptAfter - paidAfter)) / 1e18 + claimableAfter;
        assert(earnedAfter == expectedAfter);
    }
}

