contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted;
        try c.stakeFor(address(this), amount) { reverted = false; } catch { reverted = true; }

        uint256 balAfter = c.balanceOf(address(this));

        if (amount == 0) {
            // A zero stake must revert, and must not change the recorded balance.
            assert(reverted && balAfter == balBefore);
        } else {
            // If the call completes, the balance must grow by exactly the staked amount.
            // If it reverts, the balance must be unchanged.
            assert(reverted ? (balAfter == balBefore) : (balAfter == balBefore + amount));
        }
    }
}

