    constructor(C _c) { c = _c; }

    function run(address token, uint256 amount) public {
        require(token != address(0));
        require(token.code.length > 0);

        // Register token as a reward token so the 'unknown reward token' condition is not the deciding factor.
        // addReward sets lastUpdateTime and periodFinish to block.timestamp.
        c.addReward(token);

        uint40 periodFinishBefore = c.rewardPeriodFinish(token);

        // The test contract is the owner, so rewardDistributor is whatever was set at construction.
        // We must call notifyRewardAmount as the rewardDistributor. Since msg.sender for the call
        // is this test contract, we set rewardDistributor to address(this) to ensure the distributor check passes,
        // so that the rule is about the amount/token conditions rather than the caller check.
        // (Only the owner can call setRewardDistributor; this test contract is the owner.)
        c.setRewardDistributor(address(this));

        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 periodFinishAfter = c.rewardPeriodFinish(token);

        if (amount == 0) {
            // Zero amount must revert and must not change the reward period.
            assert(reverted && periodFinishAfter == periodFinishBefore);
        } else {
            // Positive amount with a registered token and correct distributor must succeed
            // and extend the period beyond the previous finish.
            assert(!reverted && periodFinishAfter > periodFinishBefore);
        }
    }
}

