    }

    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        address beforeOwner = c.owner();
        require(beforeOwner != address(0));

        if (stakeAmount > 0) {
            uint256 bal = c.stakingToken().balanceOf(address(this));
            if (bal >= stakeAmount) {
