contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address d, address token) public {
        require(d != address(0), "use nonzero migrator");

        // Baseline: read public surface before setMigrator
        uint40 beforeFinish = c.rewardPeriodFinish(token);

        // Deciding call: setMigrator is owner-only; this test contract is the owner
        c.setMigrator(d);

        // Try addReward to observe whether public surface still responds
        bool addOk;
        try c.addReward(token) { addOk = true; } catch { addOk = false; }

        // Read values through public surface after setMigrator
        address observedMigrator = c.migrator();
        uint40 afterFinish = c.rewardPeriodFinish(token);

        // General rule:
        // 1) After setMigrator(d), migrator() equals d exactly.
        // 2) The call to setMigrator does not disturb existing reward metadata: if
        //    the token was already registered (beforeFinish != 0), afterFinish is
        //    still nonzero; if it was not registered, addReward may succeed and
        //    then afterFinish becomes nonzero.
        // 3) The contract remains usable: addReward either succeeds or fails, but
        //    in either case the migrator value is unchanged from d.
        assert(
            observedMigrator == d &&
            (beforeFinish != 0 ? afterFinish != 0 : true) &&
            (addOk || afterFinish != 0 || beforeFinish == 0) &&
            c.migrator() == d
        );
    }

    receive() external payable {}
}

